export const galleryPageSources: Record<string, string> = {
  "/components/page-header": "<script setup lang=\"ts\">\nimport { RButton, RButtonGroup, RPageHeader } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <r-page-header\n          title=\"Instances\"\n          subtitle=\"Manage server lifecycle, runtime policy, and operational state.\"\n        >\n          <template #actions>\n            <r-button type=\"primary\" color=\"primary\" icon=\"fas fa-plus\">Create</r-button>\n          </template>\n        </r-page-header>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-page-header title=\"Paper EU-1\" subtitle=\"Online · Java 21 · 4 GB memory\">\n          <template #actions>\n            <r-button-group>\n              <r-button icon=\"fas fa-rotate-right\">Restart</r-button>\n              <r-button type=\"primary\" color=\"danger\" icon=\"fas fa-stop\">Stop</r-button>\n            </r-button-group>\n          </template>\n        </r-page-header>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n",
  "/components/panel": "<script setup lang=\"ts\">\nimport { RButton, RMessage, RPanel, RTag } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"panel-grid\">\n          <r-panel header=\"Default panel\">\n            Panels group related content with a header, body, border, and optional divider.\n          </r-panel>\n          <r-panel header=\"Header extra\">\n            <template #header-extra>\n              <r-tag color=\"primary\">Live</r-tag>\n            </template>\n            Header extra content stays aligned with the title and does not affect body rhythm.\n          </r-panel>\n          <r-panel header=\"Small\" size=\"small\">\n            Small panels are useful for dense controls.\n          </r-panel>\n          <r-panel header=\"Large\" size=\"large\" shadow=\"hover\">\n            Large panels have roomier spacing and optional hover elevation.\n          </r-panel>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"panel-demo-stack\">\n          <r-panel class=\"settings-panel\" header=\"Instance policy\" shadow=\"hover\">\n            <template #header-extra>\n              <r-tag color=\"success\">Online</r-tag>\n            </template>\n            <div class=\"settings-row\">\n              <div>\n                <strong>Paper EU-1</strong>\n                <p>Runtime limits, backup policy, and operator-facing actions.</p>\n              </div>\n            </div>\n            <r-message color=\"help\" title=\"Panel as a section primitive\">\n              Use Panel for bounded work areas where header actions and scrollable content matter.\n            </r-message>\n            <template #footer>\n              <div class=\"panel-footer\">\n                Last policy sync: 18 minutes ago\n              </div>\n            </template>\n            <template #action>\n              <r-button icon=\"fas fa-rotate-right\">Restart</r-button>\n              <r-button type=\"primary\" color=\"primary\" icon=\"fas fa-save\">Save</r-button>\n            </template>\n          </r-panel>\n          <r-panel class=\"scroll-panel\" header=\"Recent events\" scrollable>\n            <p v-for=\"index in 12\" :key=\"index\">\n              Event {{ index }}: panel headers and dividers stay fixed while the body scrolls.\n            </p>\n          </r-panel>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.panel-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.settings-panel {\n  max-width: 680px;\n}\n\n.panel-demo-stack {\n  display: grid;\n  gap: 16px;\n}\n\n.settings-row {\n  display: flex;\n  justify-content: space-between;\n  gap: 16px;\n  align-items: flex-start;\n}\n\n.settings-row strong {\n  color: var(--mcsl-text-color-primary);\n  font-weight: 650;\n}\n\n.settings-row p {\n  margin: 6px 0 0;\n  color: var(--mcsl-text-color-secondary);\n  line-height: 1.6;\n}\n\n.panel-footer {\n  color: var(--mcsl-text-color-secondary);\n  font-size: var(--mcsl-font-size-sm);\n}\n\n.scroll-panel {\n  max-width: 680px;\n  height: 260px;\n}\n\n.scroll-panel p {\n  margin: 0;\n  color: var(--mcsl-text-color-regular);\n  line-height: 1.7;\n}\n\n.scroll-panel p + p {\n  margin-top: 10px;\n}\n\n@media (max-width: 820px) {\n  .panel-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .settings-row {\n    flex-direction: column;\n  }\n}\n</style>\n",
  "/components/buttons": "<script setup lang=\"ts\">\nimport { RBadge, RButton, RButtonGroup, RSplitButton } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst menu = [\n  { label: \"Duplicate\", icon: \"fas fa-copy\" },\n  { label: \"Export\", icon: \"fas fa-arrow-up-from-bracket\" },\n  { label: \"Archive\", icon: \"fas fa-box-archive\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"button-layout\">\n          <div class=\"button-row\">\n            <r-button type=\"primary\" color=\"primary\" icon=\"fas fa-check\">\n              Primary\n            </r-button>\n            <r-button icon=\"fas fa-sliders\">Default</r-button>\n            <r-button type=\"dashed\" icon=\"fas fa-plus\">Dashed</r-button>\n            <r-button type=\"text\" icon=\"fas fa-ellipsis\">Text</r-button>\n          </div>\n\n          <div class=\"button-row\">\n            <r-button color=\"success\" icon=\"fas fa-circle-check\">Success</r-button>\n            <r-button color=\"warning\" icon=\"fas fa-triangle-exclamation\">\n              Warning\n            </r-button>\n            <r-button color=\"danger\" icon=\"fas fa-trash\">Danger</r-button>\n            <r-button disabled icon=\"fas fa-ban\">Disabled</r-button>\n          </div>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"button-layout\">\n          <section class=\"button-demo-block\">\n            <h3>{{ $t(\"gallery.sections.buttonGroup\") }}</h3>\n            <r-button-group>\n              <r-button type=\"primary\" color=\"primary\">Start</r-button>\n              <r-button>Restart</r-button>\n              <r-button>Stop</r-button>\n              <r-button type=\"text\" icon=\"fas fa-gear\" squared />\n            </r-button-group>\n          </section>\n\n          <section class=\"button-demo-block\">\n            <h3>{{ $t(\"gallery.sections.splitButton\") }}</h3>\n            <r-split-button color=\"primary\" type=\"primary\" :dropdown-menu=\"menu\">\n              Deploy\n            </r-split-button>\n          </section>\n\n          <section class=\"button-demo-block\">\n            <h3>{{ $t(\"gallery.sections.iconButton\") }}</h3>\n            <div class=\"button-row button-row--compact\">\n              <r-button icon=\"fas fa-rotate-right\" squared />\n              <r-button icon=\"fas fa-download\" squared />\n              <r-button icon=\"fas fa-arrow-up-right-from-square\" squared />\n              <r-button icon=\"fas fa-xmark\" color=\"danger\" squared />\n            </div>\n          </section>\n\n          <section class=\"button-demo-block\">\n            <h3>{{ $t(\"gallery.sections.loading\") }}</h3>\n            <div class=\"button-row\">\n              <r-button loading type=\"primary\" color=\"primary\">Saving</r-button>\n              <r-button loading loading-icon-pos=\"left\">Checking</r-button>\n            </div>\n          </section>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.button-layout {\n  display: grid;\n  gap: 18px;\n}\n\n.button-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 10px;\n}\n\n.button-row--compact {\n  gap: 8px;\n}\n\n.button-demo-block {\n  display: grid;\n  gap: 10px;\n}\n\n.button-demo-block h3 {\n  margin: 0;\n  color: var(--mcsl-text-color-secondary);\n  font-size: var(--mcsl-font-size-sm);\n  font-weight: 600;\n}\n</style>\n",
  "/components/input": "<script setup lang=\"ts\">\nimport { RInputNumber, RInputText, RTextarea } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst name = ref(\"Future Paper EU-1\");\nconst smallName = ref(\"Small input\");\nconst mediumName = ref(\"Medium input\");\nconst largeName = ref(\"Large input\");\nconst password = ref(\"correct-horse-battery-staple\");\nconst memory = ref(\"4096\");\nconst limitedName = ref(\"Future Paper\");\nconst searchText = ref(\"backup\");\nconst note = ref(\"A quiet resize interaction matters when the user is editing long server notes.\");\nconst command = ref(\"java -Xms2G -Xmx4G -jar server.jar nogui\");\nconst port = ref(25565);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample title=\"Inputs\">\n        <div class=\"input-layout\">\n          <label class=\"input-field\">\n            <span>Instance</span>\n            <r-input-text v-model=\"name\" clearable placeholder=\"Instance name\" />\n          </label>\n          <label class=\"input-field\">\n            <span>Password</span>\n            <r-input-text v-model=\"password\" password placeholder=\"Password\" />\n          </label>\n          <label class=\"input-field\">\n            <span>Memory</span>\n            <r-input-text v-model=\"memory\" prefix=\"RAM\" suffix=\"MB\" placeholder=\"4096\" />\n          </label>\n          <label class=\"input-field\">\n            <span>Limited</span>\n            <r-input-text v-model=\"limitedName\" :maxlength=\"16\" placeholder=\"Instance alias\" />\n          </label>\n          <label class=\"input-field\">\n            <span>Search</span>\n            <r-input-text v-model=\"searchText\" search clearable placeholder=\"Search instances\" />\n          </label>\n          <label class=\"input-field\">\n            <span>Port</span>\n            <r-input-number v-model=\"port\" :min=\"1\" :max=\"65535\" />\n          </label>\n          <label class=\"input-field input-field--wide\">\n            <span>Notes</span>\n            <r-textarea v-model=\"note\" placeholder=\"Server notes\" />\n          </label>\n        </div>\n      </GalleryExample>\n\n      <GalleryExample title=\"Sizes\">\n        <div class=\"sizes-layout\">\n          <label class=\"input-field\">\n            <span>Small</span>\n            <r-input-text v-model=\"smallName\" size=\"small\" clearable />\n          </label>\n          <label class=\"input-field\">\n            <span>Medium</span>\n            <r-input-text v-model=\"mediumName\" size=\"medium\" clearable />\n          </label>\n          <label class=\"input-field\">\n            <span>Large</span>\n            <r-input-text v-model=\"largeName\" size=\"large\" clearable />\n          </label>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample title=\"Resize Control\">\n        <div class=\"resize-layout\">\n          <label class=\"input-field\">\n            <span>Resize X</span>\n            <r-input-text v-model=\"name\" resize-x clearable />\n          </label>\n          <label class=\"input-field\">\n            <span>Resize Y</span>\n            <r-textarea v-model=\"command\" resize-y />\n          </label>\n          <label class=\"input-field\">\n            <span>Resize X + Y</span>\n            <r-textarea v-model=\"note\" resize-x resize-y />\n          </label>\n          <label class=\"input-field\">\n            <span>Locked</span>\n            <r-textarea v-model=\"note\" />\n          </label>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.input-layout,\n.resize-layout,\n.sizes-layout {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 16px;\n  align-items: start;\n}\n\n.resize-layout {\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n}\n\n.sizes-layout {\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  align-items: end;\n}\n\n.input-field {\n  display: grid;\n  min-width: 0;\n  gap: 8px;\n  color: var(--mcsl-text-color-secondary);\n  font-size: var(--mcsl-font-size-sm);\n  font-weight: 600;\n}\n\n.input-field > span {\n  color: inherit;\n  font-size: inherit;\n  font-weight: inherit;\n}\n\n.input-field--wide {\n  grid-column: 1 / -1;\n}\n\n@media (max-width: 960px) {\n  .resize-layout {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .sizes-layout {\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (max-width: 640px) {\n  .input-layout,\n  .resize-layout,\n  .sizes-layout {\n    grid-template-columns: 1fr;\n    gap: 12px;\n  }\n}\n</style>\n",
  "/components/number-box": "<script setup lang=\"ts\">\nimport { RInputNumber } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst port = ref(25565);\nconst memory = ref(4096);\nconst players = ref(20);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"number-grid\">\n          <r-input-number v-model=\"port\" :min=\"1\" :max=\"65535\" />\n          <r-input-number v-model=\"memory\" :step=\"512\" :min=\"1024\" />\n          <r-input-number v-model=\"players\" size=\"small\" :min=\"1\" :max=\"200\" />\n          <r-input-number v-model=\"players\" disabled />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"number-grid\">\n          <label class=\"field\">\n            <span>Port</span>\n            <r-input-number v-model=\"port\" :min=\"1\" :max=\"65535\" />\n          </label>\n          <label class=\"field\">\n            <span>Memory</span>\n            <r-input-number v-model=\"memory\" :step=\"512\" :min=\"1024\" />\n          </label>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.number-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.field {\n  display: grid;\n  gap: 8px;\n}\n\n.field span {\n  color: var(--mcsl-text-color-secondary);\n  font-size: var(--mcsl-font-size-sm);\n}\n\n@media (max-width: 760px) {\n  .number-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/combobox": "<script setup lang=\"ts\">\nimport { RCombobox, RMessage, RTag } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst command = ref(\"restart\");\nconst customCommand = ref(\"\");\nconst region = ref(\"sg\");\nconst readonlyRegion = ref(\"jp\");\nconst selectedCommands = ref([\"restart\", \"backup\"]);\n\nconst commands = [\n  { label: \"Restart server\", value: \"restart\", icon: \"fas fa-rotate\" },\n  { label: \"Create backup\", value: \"backup\", icon: \"fas fa-box-archive\" },\n  { label: \"Open console\", value: \"console\", icon: \"fas fa-terminal\" },\n  { label: \"Stop instance\", value: \"stop\", icon: \"fas fa-power-off\", disabled: true },\n];\n\nconst regions = [\n  { label: \"Singapore\", value: \"sg\", icon: \"fas fa-location-dot\" },\n  { label: \"Frankfurt\", value: \"de\", icon: \"fas fa-location-dot\" },\n  { label: \"Los Angeles\", value: \"us\", icon: \"fas fa-location-dot\" },\n  { label: \"Tokyo\", value: \"jp\", icon: \"fas fa-location-dot\" },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample title=\"Combobox\">\n        <div class=\"combo-grid\">\n          <label>\n            <span>Editable with search</span>\n            <r-combobox\n              v-model=\"command\"\n              :options=\"commands\"\n              placeholder=\"Type or choose a command\"\n            />\n          </label>\n          <label>\n            <span>Editable without autocomplete</span>\n            <r-combobox\n              v-model:query=\"customCommand\"\n              :options=\"commands\"\n              :autocomplete=\"false\"\n              placeholder=\"Keep all options visible\"\n            />\n          </label>\n          <label>\n            <span>Non-editable</span>\n            <r-combobox\n              v-model=\"readonlyRegion\"\n              :options=\"regions\"\n              :editable=\"false\"\n              :autocomplete=\"false\"\n              placeholder=\"Select region\"\n            />\n          </label>\n          <label>\n            <span>Multiple</span>\n            <r-combobox\n              v-model=\"selectedCommands\"\n              :options=\"commands\"\n              multiple\n              placeholder=\"Select commands\"\n            />\n          </label>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.boundValue')\">\n        <div class=\"combo-stack\">\n          <r-message color=\"help\" title=\"Editable query\">\n            {{ customCommand || command }}\n          </r-message>\n          <div class=\"tag-row\">\n            <r-tag color=\"primary\">Region: {{ region }}</r-tag>\n            <r-tag color=\"success\">Readonly: {{ readonlyRegion }}</r-tag>\n            <r-tag color=\"warning\">Multiple: {{ selectedCommands.join(\", \") }}</r-tag>\n          </div>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.combo-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\nlabel,\n.combo-stack {\n  display: grid;\n  gap: 8px;\n}\n\nlabel > span {\n  color: var(--mcsl-text-color-secondary);\n  font-size: var(--mcsl-font-size-sm);\n  font-weight: 650;\n}\n\n.tag-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n@media (max-width: 720px) {\n  .combo-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/date-time": "<script setup lang=\"ts\">\nimport { RCalendar, RDatePicker, RMessage, RTimePicker } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst date = ref(\"2026-06-10\");\nconst time = ref(\"21:30\");\nconst maintenanceDate = ref(\"\");\nconst maintenanceTime = ref(\"\");\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample title=\"Date & Time\">\n        <div class=\"date-grid\">\n          <label>\n            <span>Deployment date</span>\n            <r-date-picker v-model=\"date\" min=\"2026-01-01\" max=\"2026-12-31\" />\n          </label>\n          <label>\n            <span>Restart time</span>\n            <r-time-picker v-model=\"time\" min=\"00:00\" max=\"23:59\" />\n          </label>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample title=\"Maintenance Window\">\n        <div class=\"date-stack\">\n          <r-calendar v-model=\"maintenanceDate\" min=\"2026-01-01\" max=\"2026-12-31\" />\n          <div class=\"date-grid\">\n            <label>\n              <span>Date</span>\n              <r-date-picker v-model=\"maintenanceDate\" placeholder=\"Pick date\" clearable />\n            </label>\n            <label>\n              <span>Time</span>\n              <r-time-picker v-model=\"maintenanceTime\" :step=\"300\" clearable />\n            </label>\n          </div>\n          <r-message color=\"help\" title=\"Selected window\">\n            {{ maintenanceDate || \"No date\" }} {{ maintenanceTime || \"No time\" }}\n          </r-message>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.date-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.date-stack,\nlabel {\n  display: grid;\n  gap: 8px;\n}\n\nlabel > span {\n  color: var(--mcsl-text-color-secondary);\n  font-size: var(--mcsl-font-size-sm);\n  font-weight: 650;\n}\n\n@media (max-width: 720px) {\n  .date-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/slider": "<script setup lang=\"ts\">\nimport { RSlider } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst memory = ref(36);\nconst cpu = ref(72);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"slider-stack\">\n          <r-slider v-model=\"memory\" :min=\"0\" :max=\"100\" />\n          <r-slider v-model=\"cpu\" :min=\"0\" :max=\"100\" :step=\"4\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"slider-stack\">\n          <r-slider v-model=\"memory\" :min=\"0\" :max=\"100\" />\n          <r-slider v-model=\"cpu\" :min=\"0\" :max=\"100\" disabled />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.slider-stack {\n  display: grid;\n  gap: 18px;\n}\n</style>\n",
  "/components/radio": "<script setup lang=\"ts\">\nimport { RRadioGroup } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst flavor = ref(\"paper\");\nconst channel = ref(\"stable\");\n\nconst flavorOptions = [\n  { label: \"Paper\", value: \"paper\" },\n  { label: \"Fabric\", value: \"fabric\" },\n  { label: \"NeoForge\", value: \"neoforge\" },\n];\n\nconst channelOptions = [\n  { label: \"Stable\", value: \"stable\" },\n  { label: \"Snapshot\", value: \"snapshot\" },\n  { label: \"Experimental\", value: \"experimental\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"radio-stack\">\n          <r-radio-group v-model=\"flavor\" :options=\"flavorOptions\" size=\"small\" />\n          <r-radio-group v-model=\"flavor\" :options=\"flavorOptions\" />\n          <r-radio-group v-model=\"flavor\" :options=\"flavorOptions\" size=\"large\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"radio-stack\">\n          <r-radio-group v-model=\"flavor\" :options=\"flavorOptions\" />\n          <r-radio-group v-model=\"channel\" :options=\"channelOptions\" />\n          <r-radio-group v-model=\"channel\" :options=\"channelOptions\" disabled />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.radio-stack {\n  display: grid;\n  gap: 16px;\n}\n</style>\n",
  "/components/checkbox": "<script setup lang=\"ts\">\nimport { RCheckbox } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst enabled = ref(true);\nconst mixed = ref<boolean | null>(null);\nconst snapshots = ref(true);\nconst backups = ref(false);\nconst inherited = ref<boolean | null>(null);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"state-grid\">\n          <r-checkbox v-model=\"enabled\">Checked</r-checkbox>\n          <r-checkbox v-model=\"backups\">Unchecked</r-checkbox>\n          <r-checkbox v-model=\"mixed\" color=\"help\">Mixed</r-checkbox>\n          <r-checkbox v-model=\"enabled\" disabled>Disabled checked</r-checkbox>\n          <r-checkbox disabled>Disabled</r-checkbox>\n          <r-checkbox invalid>Invalid</r-checkbox>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"policy-list\">\n          <r-checkbox v-model=\"snapshots\">Allow snapshot builds</r-checkbox>\n          <r-checkbox v-model=\"backups\" color=\"success\">Run scheduled backups</r-checkbox>\n          <r-checkbox v-model=\"inherited\" color=\"help\">Inherit parent policy</r-checkbox>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.state-grid,\n.policy-list {\n  display: grid;\n  gap: 12px;\n  align-items: start;\n}\n\n.state-grid {\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n}\n\n@media (max-width: 720px) {\n  .state-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/toggle": "<script setup lang=\"ts\">\nimport { RSwitch } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst autoStart = ref(false);\nconst maintenance = ref(true);\nconst metrics = ref(true);\nconst locked = ref(false);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"toggle-grid\">\n          <label class=\"toggle-row\">\n            <r-switch v-model=\"autoStart\" size=\"small\" />\n            <span>Small</span>\n          </label>\n          <label class=\"toggle-row\">\n            <r-switch v-model=\"maintenance\" color=\"warning\" />\n            <span>Warning</span>\n          </label>\n          <label class=\"toggle-row\">\n            <r-switch v-model=\"metrics\" color=\"success\" size=\"large\" />\n            <span>Large</span>\n          </label>\n          <label class=\"toggle-row\">\n            <r-switch v-model=\"locked\" disabled />\n            <span>Disabled</span>\n          </label>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"toggle-stack\">\n          <label class=\"toggle-row\">\n            <r-switch v-model=\"autoStart\" />\n            <span>Auto-start daemon</span>\n          </label>\n          <label class=\"toggle-row\">\n            <r-switch v-model=\"maintenance\" color=\"warning\" />\n            <span>Maintenance mode</span>\n          </label>\n          <label class=\"toggle-row\">\n            <r-switch v-model=\"metrics\" color=\"success\" />\n            <span>Collect metrics</span>\n          </label>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.toggle-grid,\n.toggle-stack {\n  display: grid;\n  gap: 14px;\n}\n\n.toggle-grid {\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n}\n\n.toggle-row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  color: var(--mcsl-text-color-regular);\n}\n\n@media (max-width: 720px) {\n  .toggle-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/transfer": "<script setup lang=\"ts\">\nimport { RMessage, RTag, RTransfer } from \"reta-ui\";\nimport { computed, ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst enabledServices = ref([\"console\", \"backup\"]);\nconst selectedRegions = ref([\"sg\"]);\n\nconst serviceOptions = [\n  { label: \"Console access\", value: \"console\", icon: \"fas fa-terminal\" },\n  { label: \"Scheduled backup\", value: \"backup\", icon: \"fas fa-box-archive\" },\n  { label: \"Metrics exporter\", value: \"metrics\", icon: \"fas fa-chart-line\" },\n  { label: \"Webhook alerts\", value: \"webhook\", icon: \"fas fa-bell\" },\n  { label: \"Danger zone\", value: \"danger\", icon: \"fas fa-triangle-exclamation\", disabled: true },\n];\n\nconst regionOptions = [\n  { label: \"Singapore\", value: \"sg\", icon: \"fas fa-location-dot\" },\n  { label: \"Frankfurt\", value: \"de\", icon: \"fas fa-location-dot\" },\n  { label: \"Los Angeles\", value: \"us\", icon: \"fas fa-location-dot\" },\n  { label: \"Tokyo\", value: \"jp\", icon: \"fas fa-location-dot\" },\n  { label: \"Sydney\", value: \"au\", icon: \"fas fa-location-dot\" },\n];\n\nconst selectedServiceLabels = computed(() =>\n  serviceOptions\n    .filter((option) => enabledServices.value.includes(option.value))\n    .map((option) => option.label),\n);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <r-transfer\n          v-model=\"enabledServices\"\n          :options=\"serviceOptions\"\n          source-title=\"Disabled services\"\n          target-title=\"Enabled services\"\n          source-placeholder=\"Search disabled\"\n          target-placeholder=\"Search enabled\"\n        />\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"transfer-demo\">\n          <r-transfer\n            v-model=\"selectedRegions\"\n            :options=\"regionOptions\"\n            color=\"success\"\n            source-title=\"Available regions\"\n            target-title=\"Deployment targets\"\n          />\n          <r-message color=\"success\" title=\"Selected services\">\n            <div class=\"transfer-tags\">\n              <r-tag\n                v-for=\"label in selectedServiceLabels\"\n                :key=\"label\"\n                color=\"success\"\n                size=\"small\"\n              >\n                {{ label }}\n              </r-tag>\n            </div>\n          </r-message>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.transfer-demo {\n  display: grid;\n  gap: 16px;\n}\n\n.transfer-tags {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n</style>\n",
  "/components/result": "<script setup lang=\"ts\">\nimport { RButton, RResult } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"result-grid\">\n          <r-result title=\"Completed\" description=\"Deployment image was published.\" status=\"success\" />\n          <r-result title=\"Needs attention\" description=\"Two plugins need review.\" status=\"warning\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-result\n          title=\"Deployment completed\"\n          description=\"The server image has been rebuilt and published.\"\n          status=\"success\"\n        >\n          <div class=\"result-actions\">\n            <r-button type=\"primary\" color=\"primary\">Open Instance</r-button>\n            <r-button>View Logs</r-button>\n          </div>\n        </r-result>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.result-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.result-actions {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: center;\n  gap: 10px;\n  margin-top: 12px;\n}\n\n@media (max-width: 860px) {\n  .result-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/empty": "<script setup lang=\"ts\">\nimport { RButton, REmpty } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"empty-grid\">\n          <r-empty title=\"No running instances\" description=\"Start or import an instance to continue.\" />\n          <r-empty title=\"No backups\" description=\"Create a backup schedule before production launch.\" icon=\"fas fa-clock-rotate-left\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-empty\n          title=\"No running instances\"\n          description=\"Create a new instance or import an existing configuration.\"\n        >\n          <r-button type=\"primary\" color=\"primary\" icon=\"fas fa-plus\">Create Instance</r-button>\n        </r-empty>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.empty-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n@media (max-width: 860px) {\n  .empty-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/divider": "<script setup lang=\"ts\">\nimport { RDivider } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"divider-stack\">\n          <r-divider spacing=\"xs\" />\n          <r-divider spacing=\"sm\" variant=\"dashed\">Runtime</r-divider>\n          <r-divider spacing=\"sm\" variant=\"dotted\" text-pos=\"start\">Advanced</r-divider>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"divider-demo\">\n          <p>Instance settings</p>\n          <r-divider spacing=\"md\">Network</r-divider>\n          <p>Port, address, and proxy configuration</p>\n          <r-divider spacing=\"md\" text-pos=\"end\">Danger Zone</r-divider>\n          <p>Destructive operations stay visually separated.</p>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.divider-stack,\n.divider-demo {\n  display: grid;\n  gap: 6px;\n}\n\np {\n  margin: 0;\n  color: var(--mcsl-text-color-regular);\n}\n</style>\n",
  "/components/copyable-text": "<script setup lang=\"ts\">\nimport { RCopyableText } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"copy-stack\">\n          <r-copyable-text size=\"small\">reta-ui</r-copyable-text>\n          <r-copyable-text>paper-1.21.1-43.jar</r-copyable-text>\n          <r-copyable-text size=\"large\">ws://127.0.0.1:25567/daemon</r-copyable-text>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-copyable-text>Reta UI</r-copyable-text>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.copy-stack {\n  display: grid;\n  gap: 10px;\n  justify-items: start;\n}\n</style>\n",
  "/components/code": "<script setup lang=\"ts\">\nimport { RCode, RMessage } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\nimport { galleryCodeHighlighter } from \"../components/galleryCodeHighlighter\";\n\nconst vueExample = `<script setup lang=\"ts\">\nimport { RButton, RCode } from \"reta-ui\";\n\nconst snippet = \"const status = 'running';\";\n` + \"</scr\" + `ipt>\n\n<template>\n  <r-code :code=\"snippet\" language=\"typescript\" />\n  <r-button type=\"primary\">Deploy</r-button>\n</template>`;\n\nconst tsExample = `type InstanceStatus = \"running\" | \"stopped\";\n\nexport function formatStatus(status: InstanceStatus) {\n  return status === \"running\" ? \"Online\" : \"Offline\";\n}`;\n\nconst plainExample = `Reta UI Code component\n- Does not bundle highlight.js\n- Accepts an external hljs-compatible highlighter\n- Falls back to escaped plain text`;\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample title=\"Code\">\n        <div class=\"code-stack\">\n          <r-code\n            :code=\"vueExample\"\n            language=\"xml\"\n            :hljs=\"galleryCodeHighlighter\"\n            line-numbers\n          />\n          <r-code\n            :code=\"plainExample\"\n            language=\"plaintext\"\n            max-height=\"12rem\"\n            font-size=\"12px\"\n            word-wrap\n          />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.externalHighlighter')\">\n        <div class=\"code-stack\">\n          <r-message color=\"help\" title=\"No bundled highlighter\">\n            Code only receives an hljs-compatible object from the application.\n          </r-message>\n          <r-code\n            :code=\"tsExample\"\n            language=\"typescript\"\n            :hljs=\"galleryCodeHighlighter\"\n            line-numbers\n          />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.code-stack {\n  display: grid;\n  gap: 14px;\n}\n</style>\n",
  "/components/skeleton": "<script setup lang=\"ts\">\nimport { RAvatar, RSkeleton } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"skeleton-stack\">\n          <r-skeleton :lines=\"3\" height=\"14px\" />\n          <r-skeleton width=\"64%\" height=\"16px\" />\n          <r-skeleton width=\"36%\" height=\"28px\" :rounded=\"false\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"skeleton-card\">\n          <r-avatar text=\"LD\" />\n          <div>\n            <r-skeleton width=\"44%\" height=\"15px\" />\n            <r-skeleton :lines=\"3\" height=\"12px\" />\n          </div>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.skeleton-stack {\n  display: grid;\n  gap: 12px;\n}\n\n.skeleton-card {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr);\n  gap: 14px;\n  align-items: start;\n}\n</style>\n",
  "/components/display": "<script setup lang=\"ts\">\nimport { RAvatar, RCopyableText, REmpty, RMessage, RPanel, RResult, RSkeleton, RTable, RTag } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst columns = [\"Name\", \"Status\", \"Version\"];\nconst rows = [\n  [\"Paper EU-1\", \"Running\", \"1.21.1\"],\n  [\"Fabric Dev\", \"Stopped\", \"1.20.4\"],\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"display-grid\">\n          <r-panel size=\"small\">\n            <template #header><h4>Identity</h4></template>\n            <div class=\"inline-row\">\n              <r-avatar text=\"RF\" />\n              <r-tag color=\"primary\">Primary Tag</r-tag>\n              <r-tag color=\"success\">Healthy</r-tag>\n            </div>\n          </r-panel>\n          <r-panel size=\"small\">\n            <template #header><h4>Text</h4></template>\n            <r-copyable-text>reta-ui</r-copyable-text>\n          </r-panel>\n          <r-panel size=\"small\" class=\"display-grid__wide\">\n            <template #header><h4>Empty</h4></template>\n            <r-empty title=\"No resources yet\" description=\"Display components should communicate state with calm hierarchy.\" />\n          </r-panel>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"display-stack\">\n          <r-message title=\"Heads up\" color=\"warning\">\n            This is a lightweight message surface for inline guidance.\n          </r-message>\n          <r-result title=\"Deployment completed\" description=\"Use result states for larger success or failure summaries.\" status=\"success\" />\n          <r-table :columns=\"columns\" :rows=\"rows\" />\n          <r-skeleton :lines=\"4\" height=\"14px\" />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.display-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.display-grid__wide {\n  grid-column: 1 / -1;\n}\n\n.display-stack {\n  display: grid;\n  gap: 16px;\n}\n\n.inline-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  align-items: center;\n}\n\n@media (max-width: 860px) {\n  .display-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/feedback": "<script setup lang=\"ts\">\nimport { REmpty, RMessage, RMeterGroup, RPanel, RResult, RSkeleton } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst healthyMeter = {\n  length: 100,\n  values: [\n    { label: \"CPU\", length: 18, type: \"success\" },\n    { label: \"RAM\", length: 42, type: \"primary\" },\n  ],\n};\n\nconst attentionMeter = {\n  length: 100,\n  values: [\n    { label: \"Latency\", length: 64, type: \"warning\" },\n    { label: \"Disk\", length: 51, type: \"help\" },\n  ],\n};\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"status-grid\">\n          <r-panel size=\"small\">\n            <template #header><h4>Healthy</h4></template>\n            <div class=\"feedback-card\">\n              <r-message color=\"success\" title=\"Stable\">CPU 18% · Memory 1.2 GB</r-message>\n              <r-meter-group :meter=\"healthyMeter\" />\n            </div>\n          </r-panel>\n          <r-panel size=\"small\">\n            <template #header><h4>Attention</h4></template>\n            <div class=\"feedback-card\">\n              <r-message color=\"warning\" title=\"Queue rising\">Latency increased.</r-message>\n              <r-meter-group :meter=\"attentionMeter\" />\n            </div>\n          </r-panel>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"feedback-stack\">\n          <r-result title=\"Backup completed\" description=\"Snapshot and metadata have been stored.\" status=\"success\" />\n          <r-empty title=\"No running instances\" description=\"Use this state to explain the next meaningful action.\" />\n          <r-skeleton :lines=\"3\" height=\"14px\" />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.status-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.feedback-card,\n.feedback-stack {\n  display: grid;\n  gap: 14px;\n}\n\n@media (max-width: 980px) {\n  .status-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/navigation": "<script setup lang=\"ts\">\nimport { RBreadcrumbs, RNavTabs, RPanel, RSidebar } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst crumbs = [\n  { label: \"Reta Future\", icon: \"fas fa-cube\" },\n  { label: \"Gallery\" },\n  { label: \"Navigation\" },\n];\n\nconst pages = [\n  { label: \"Overview\", description: \"Status\", icon: \"fas fa-gauge\", link: \"/components/navigation\" },\n  { label: \"Instances\", description: \"Fleet\", icon: \"fas fa-server\" },\n  { label: \"Settings\", description: \"Policy\", icon: \"fas fa-gear\" },\n];\n\nconst tabs = [\n  { label: \"Details\", icon: \"fas fa-circle-info\" },\n  { label: \"Metrics\", icon: \"fas fa-chart-line\" },\n  { label: \"History\", icon: \"fas fa-clock-rotate-left\" },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"navigation-stack\">\n          <r-breadcrumbs :items=\"crumbs\" />\n          <r-nav-tabs :tabs=\"tabs\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"nav-grid\">\n          <r-panel size=\"small\">\n            <template #header><h4>Sidebar</h4></template>\n            <r-sidebar :pages=\"pages\" />\n          </r-panel>\n          <r-panel size=\"small\">\n            <template #header><h4>Top Navigation</h4></template>\n            <div class=\"navigation-stack\">\n              <r-breadcrumbs :items=\"crumbs\" />\n              <r-nav-tabs :tabs=\"tabs\" shadow=\"hover\" />\n            </div>\n          </r-panel>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.navigation-stack {\n  display: grid;\n  gap: 14px;\n  justify-items: start;\n}\n\n.nav-grid {\n  display: grid;\n  grid-template-columns: minmax(220px, 0.7fr) minmax(0, 1.3fr);\n  gap: 14px;\n}\n\n@media (max-width: 920px) {\n  .nav-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/breadcrumbs": "<script setup lang=\"ts\">\nimport { RBreadcrumbs } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst baseCrumbs = [\n  { label: \"Reta Future\", icon: \"fas fa-cube\" },\n  { label: \"Instances\" },\n  { label: \"Paper EU-1\" },\n];\n\nconst linkedCrumbs = [\n  { label: \"Gallery\", link: \"/components/buttons\" },\n  { label: \"Navigation\", link: \"/components/navigation\" },\n  { label: \"Breadcrumbs\" },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"crumb-stack\">\n          <r-breadcrumbs :items=\"baseCrumbs\" />\n          <r-breadcrumbs :items=\"linkedCrumbs\" seperator=\">\" />\n          <r-breadcrumbs :items=\"baseCrumbs\" seperator=\"·\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-breadcrumbs :items=\"linkedCrumbs\" />\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.crumb-stack {\n  display: grid;\n  gap: 14px;\n}\n</style>\n",
  "/components/sidebar": "<script setup lang=\"ts\">\nimport { RPanel, RSidebar } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst pages = [\n  { label: \"Overview\", description: \"Status\", icon: \"fas fa-gauge\", link: \"/components/sidebar\" },\n  { label: \"Instances\", description: \"Fleet\", icon: \"fas fa-server\" },\n  { label: \"Backups\", description: \"Jobs\", icon: \"fas fa-clock-rotate-left\" },\n  { label: \"Settings\", description: \"Policy\", icon: \"fas fa-gear\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"sidebar-grid\">\n          <r-panel size=\"small\">\n            <template #header><h4>Expanded</h4></template>\n            <r-sidebar :pages=\"pages\" />\n          </r-panel>\n          <r-panel size=\"small\" class=\"collapsed-card\">\n            <template #header><h4>Collapsed</h4></template>\n            <r-sidebar :pages=\"pages\" collapsed />\n          </r-panel>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-sidebar :pages=\"pages\" />\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.sidebar-grid {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 96px;\n  gap: 14px;\n  align-items: start;\n}\n\n.collapsed-card {\n  justify-self: start;\n  width: 78px;\n}\n\n@media (max-width: 760px) {\n  .sidebar-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/nav-tabs": "<script setup lang=\"ts\">\nimport { RNavTabs } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst tabs = [\n  { label: \"Details\", icon: \"fas fa-circle-info\" },\n  { label: \"Metrics\", icon: \"fas fa-chart-line\" },\n  { label: \"History\", icon: \"fas fa-clock-rotate-left\" },\n  { label: \"Danger\", icon: \"fas fa-triangle-exclamation\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"tabs-stack\">\n          <r-nav-tabs :tabs=\"tabs\" size=\"small\" />\n          <r-nav-tabs :tabs=\"tabs\" />\n          <r-nav-tabs :tabs=\"tabs\" size=\"large\" color=\"help\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-nav-tabs :tabs=\"tabs\" shadow=\"hover\" />\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.tabs-stack {\n  display: grid;\n  gap: 14px;\n  justify-items: start;\n}\n</style>\n",
  "/components/steps": "<script setup lang=\"ts\">\nimport { RMessage, RSteps } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst current = ref(1);\n\nconst installSteps = [\n  { title: \"Profile\", description: \"Select loader and version\" },\n  { title: \"Resources\", description: \"Allocate memory and ports\" },\n  { title: \"Review\", description: \"Confirm launch settings\" },\n  { title: \"Launch\", description: \"Start the instance\" },\n];\n\nconst taskSteps = [\n  { title: \"Queued\", description: \"Waiting for daemon slot\" },\n  { title: \"Downloading\", description: \"Fetching server artifacts\" },\n  { title: \"Verify\", description: \"Hash and metadata checks\", status: \"error\" as const },\n  { title: \"Done\", description: \"Ready to launch\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample title=\"Steps\">\n        <div class=\"steps-stack\">\n          <r-steps v-model=\"current\" :items=\"installSteps\" clickable />\n          <r-steps :items=\"installSteps\" :model-value=\"2\" size=\"small\" color=\"success\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.installFlow')\">\n        <div class=\"steps-demo\">\n          <r-steps v-model=\"current\" :items=\"installSteps\" clickable color=\"primary\" />\n          <r-message color=\"help\" title=\"Selected step\">\n            {{ installSteps[current]?.title }} - {{ installSteps[current]?.description }}\n          </r-message>\n          <r-steps :items=\"taskSteps\" :model-value=\"1\" vertical color=\"warning\" />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.steps-stack,\n.steps-demo {\n  display: grid;\n  gap: 18px;\n}\n</style>\n",
  "/components/dropdown": "<script setup lang=\"ts\">\nimport { RButton, RButtonGroup, RDropdownMenu } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst menu = [\n  { label: \"Open settings\", icon: \"fas fa-gear\" },\n  { label: \"Duplicate instance\", icon: \"fas fa-copy\" },\n  { label: \"Archive\", icon: \"fas fa-box-archive\", disabled: true },\n];\n\nconst groupedMenu = [\n  {\n    group: \"Instance\",\n    items: [\n      { label: \"Start\", icon: \"fas fa-play\" },\n      { label: \"Restart\", icon: \"fas fa-rotate-right\" },\n    ],\n  },\n  {\n    group: \"Danger\",\n    items: [{ label: \"Delete\", icon: \"fas fa-trash\", color: \"danger\" }],\n  },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"overlay-row\">\n          <r-dropdown-menu :menu=\"menu\">\n            <template #triggerer=\"{ toggle }\">\n              <r-button icon=\"fas fa-ellipsis\" @click=\"toggle\">Default</r-button>\n            </template>\n          </r-dropdown-menu>\n          <r-dropdown-menu :menu=\"groupedMenu\" default-pos=\"top\">\n            <template #triggerer=\"{ toggle }\">\n              <r-button icon=\"fas fa-arrow-up\" @click=\"toggle\">Top</r-button>\n            </template>\n          </r-dropdown-menu>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-button-group>\n          <r-button type=\"primary\" color=\"primary\">Start</r-button>\n          <r-dropdown-menu :menu=\"groupedMenu\">\n            <template #triggerer=\"{ toggle }\">\n              <r-button icon=\"fas fa-angle-down\" squared @click=\"toggle\" />\n            </template>\n          </r-dropdown-menu>\n        </r-button-group>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  align-items: center;\n}\n</style>\n",
  "/components/drawer": "<script setup lang=\"ts\">\nimport { RButton, RDrawer, RMessage, RTag } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst rightVisible = ref(false);\nconst bottomVisible = ref(false);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"overlay-row\">\n          <r-button type=\"primary\" color=\"primary\" @click=\"rightVisible = true\">Right Drawer</r-button>\n          <r-button @click=\"bottomVisible = true\">Bottom Drawer</r-button>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-button type=\"primary\" color=\"primary\" icon=\"fas fa-sidebar\" @click=\"rightVisible = true\">\n          Open Drawer\n        </r-button>\n        <r-drawer v-model:visible=\"rightVisible\" title=\"Instance Details\">\n          <div class=\"drawer-stack\">\n            <r-message title=\"Paper EU-1\" color=\"success\" variant=\"outlined\">\n              Running on Java 21 with 12 active players.\n            </r-message>\n            <div class=\"tag-row\">\n              <r-tag color=\"primary\">Paper</r-tag>\n              <r-tag color=\"success\">Online</r-tag>\n              <r-tag color=\"help\">4 GB</r-tag>\n            </div>\n          </div>\n          <template #footer=\"{ close }\">\n            <r-button @click=\"close\">Close</r-button>\n            <r-button type=\"primary\" color=\"primary\">Open Console</r-button>\n          </template>\n        </r-drawer>\n        <r-drawer v-model:visible=\"bottomVisible\" title=\"Task Queue\" placement=\"bottom\">\n          <r-message title=\"Backup queued\" color=\"help\">The next scheduled backup starts after upload.</r-message>\n        </r-drawer>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row,\n.tag-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n  align-items: center;\n}\n\n.drawer-stack {\n  display: grid;\n  gap: 14px;\n}\n</style>\n",
  "/components/confirm-dialog": "<script setup lang=\"ts\">\nimport { RButton, RConfirmDialog } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst deleteVisible = ref(false);\nconst restartVisible = ref(false);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"overlay-row\">\n          <r-button color=\"warning\" @click=\"restartVisible = true\">Restart</r-button>\n          <r-button color=\"danger\" type=\"primary\" @click=\"deleteVisible = true\">Delete</r-button>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-button color=\"danger\" type=\"primary\" icon=\"fas fa-trash\" @click=\"deleteVisible = true\">\n          Delete Instance\n        </r-button>\n        <r-confirm-dialog\n          v-model:visible=\"deleteVisible\"\n          title=\"Delete instance?\"\n          description=\"This removes the instance record from the launcher. Server files are not deleted automatically.\"\n          confirm-text=\"Delete\"\n          cancel-text=\"Keep\"\n        />\n        <r-confirm-dialog\n          v-model:visible=\"restartVisible\"\n          title=\"Restart instance?\"\n          description=\"Players will be disconnected while the process restarts.\"\n          color=\"warning\"\n          confirm-text=\"Restart\"\n          cancel-text=\"Cancel\"\n        />\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n</style>\n",
  "/components/tooltip": "<script setup lang=\"ts\">\nimport { RButton, RTooltip } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"overlay-row\">\n          <r-tooltip content=\"Start the selected instance.\">\n            <template #triggerer=\"{ open, close }\">\n              <r-button @mouseenter=\"open\" @mouseleave=\"close\">Top</r-button>\n            </template>\n          </r-tooltip>\n          <r-tooltip content=\"Opens in a side panel.\" default-pos=\"right\">\n            <template #triggerer=\"{ open, close }\">\n              <r-button @mouseenter=\"open\" @mouseleave=\"close\">Right</r-button>\n            </template>\n          </r-tooltip>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-tooltip content=\"Helpful detail for this action.\">\n          <template #triggerer=\"{ open, close }\">\n            <r-button icon=\"fas fa-circle-info\" @mouseenter=\"open\" @mouseleave=\"close\">\n              Hover me\n            </r-button>\n          </template>\n        </r-tooltip>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n</style>\n",
  "/components/popover": "<script setup lang=\"ts\">\nimport { RButton, RMessage, RPopover, RTag } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"overlay-row\">\n          <r-popover title=\"Inspector\">\n            <template #triggerer=\"{ toggle }\">\n              <r-button @click=\"toggle\">Bottom</r-button>\n            </template>\n            <r-message color=\"help\" variant=\"text\">Compact contextual content.</r-message>\n          </r-popover>\n          <r-popover title=\"Status\" default-pos=\"right\">\n            <template #triggerer=\"{ toggle }\">\n              <r-button @click=\"toggle\">Right</r-button>\n            </template>\n            <r-tag color=\"success\">Online</r-tag>\n          </r-popover>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-popover title=\"Inspector\">\n          <template #triggerer=\"{ toggle }\">\n            <r-button icon=\"fas fa-magnifying-glass-chart\" @click=\"toggle\">Open Popover</r-button>\n          </template>\n          <div class=\"popover-body\">\n            <r-tag color=\"success\">Running</r-tag>\n            <span>12 players · 41 ms latency</span>\n          </div>\n        </r-popover>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row,\n.popover-body {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n  align-items: center;\n}\n\n.popover-body {\n  color: var(--mcsl-text-color-regular);\n}\n</style>\n",
  "/components/modal": "<script setup lang=\"ts\">\nimport { RButton, RMessage, RModal } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst previewVisible = ref(false);\nconst formVisible = ref(false);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"overlay-row\">\n          <r-button @click=\"previewVisible = true\">Preview</r-button>\n          <r-button type=\"primary\" color=\"primary\" @click=\"formVisible = true\">Create</r-button>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <r-button icon=\"fas fa-window-restore\" @click=\"previewVisible = true\">Open Modal</r-button>\n        <r-modal v-model:visible=\"previewVisible\" header=\"Modal Preview\" max-width=\"520px\">\n          <r-message title=\"Paper EU-1\" color=\"help\">\n            Modal surfaces stay focused and short.\n          </r-message>\n        </r-modal>\n        <r-modal v-model:visible=\"formVisible\" header=\"Create Instance\" max-width=\"560px\">\n          <r-message title=\"Template selected\" color=\"success\">\n            Paper 1.21.1 with Java 21 runtime.\n          </r-message>\n        </r-modal>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n</style>\n",
  "/components/contextmenu": "<script setup lang=\"ts\">\nimport { RContextmenu, RTag } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst target = ref<HTMLElement | null>(null);\nconst menu = [\n  { label: \"Rename\", icon: \"fas fa-pen\" },\n  { label: \"Duplicate\", icon: \"fas fa-copy\" },\n  { label: \"Delete\", icon: \"fas fa-trash\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"context-target context-target--small\">\n          <r-tag color=\"help\">Right click</r-tag>\n          <span>Scoped menu target</span>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div ref=\"target\" class=\"context-target\">\n          <r-tag color=\"primary\">Instance</r-tag>\n          <span>Right click this area</span>\n        </div>\n        <r-contextmenu :parent=\"target as any\" :menu=\"menu\" />\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.context-target {\n  min-height: 140px;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  border: 1px dashed color-mix(in srgb, var(--mcsl-border-color-base) 86%, transparent);\n  border-radius: var(--mcsl-border-radius-sm);\n  color: var(--mcsl-text-color-secondary);\n  background: color-mix(in srgb, var(--mcsl-bg-color-overlay) 94%, transparent);\n}\n\n.context-target--small {\n  min-height: 92px;\n}\n</style>\n",
  "/components/overlays": "<script setup lang=\"ts\">\nimport { RButton, RDropdownMenu, RPopover, RTooltip } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst menu = [\n  { label: \"Open settings\", icon: \"fas fa-gear\" },\n  { label: \"Duplicate instance\", icon: \"fas fa-copy\" },\n  { label: \"Archive\", icon: \"fas fa-box-archive\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"overlay-demo\">\n          <r-dropdown-menu :menu=\"menu\">\n            <template #triggerer=\"{ toggle }\">\n              <r-button @click=\"toggle\">Dropdown</r-button>\n            </template>\n          </r-dropdown-menu>\n          <r-tooltip content=\"Fast inline hint.\">\n            <template #triggerer=\"{ open, close }\">\n              <r-button @mouseenter=\"open\" @mouseleave=\"close\">Tooltip</r-button>\n            </template>\n          </r-tooltip>\n          <r-popover title=\"Inspector\">\n            <template #triggerer=\"{ toggle }\">\n              <r-button @click=\"toggle\">Popover</r-button>\n            </template>\n            <p class=\"overlay-note\">Compact contextual surface.</p>\n          </r-popover>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"overlay-demo\">\n          <r-dropdown-menu :menu=\"menu\">\n            <template #triggerer=\"{ toggle }\">\n              <r-button icon=\"fas fa-ellipsis\" @click=\"toggle\">Open Menu</r-button>\n            </template>\n          </r-dropdown-menu>\n          <r-popover title=\"Instance\">\n            <template #triggerer=\"{ toggle }\">\n              <r-button icon=\"fas fa-circle-info\" @click=\"toggle\">Inspect</r-button>\n            </template>\n            <p class=\"overlay-note\">Paper EU-1 · Online · 12 players</p>\n          </r-popover>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-demo {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  align-items: center;\n}\n\n.overlay-note {\n  margin: 0;\n  color: var(--mcsl-text-color-regular);\n  line-height: 1.6;\n}\n</style>\n",
  "/components/progress": "<script setup lang=\"ts\">\nimport { RProgressBar, RSpinner } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"progress-stack\">\n          <r-progress-bar :progress=\"64\" status=\"loading\" />\n          <r-progress-bar :progress=\"100\" status=\"success\" />\n          <r-progress-bar :progress=\"42\" status=\"warning\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"progress-stack\">\n          <r-progress-bar variant=\"indeterminate\" status=\"loading\" />\n          <r-progress-bar variant=\"circle\" :progress=\"72\" status=\"loading\" />\n          <r-spinner label=\"Syncing\" />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.progress-stack {\n  display: grid;\n  gap: 16px;\n}\n</style>\n",
  "/components/pagination": "<script setup lang=\"ts\">\nimport { RItemsPagination, RPagination } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst shortPage = ref(2);\nconst longPage = ref(8);\nconst itemPage = ref(3);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"pagination-stack\">\n          <r-pagination v-model:page=\"shortPage\" :length=\"5\" size=\"small\" />\n          <r-pagination v-model:page=\"longPage\" :length=\"16\" />\n          <r-pagination v-model:page=\"longPage\" :length=\"128\" size=\"large\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"pagination-stack\">\n          <r-pagination v-model:page=\"longPage\" :length=\"16\" />\n          <r-items-pagination v-model:page=\"itemPage\" :item-per-page=\"20\" :total=\"240\" />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.pagination-stack {\n  display: grid;\n  gap: 16px;\n  justify-items: start;\n}\n</style>\n",
  "/components/upload": "<script setup lang=\"ts\">\nimport { RFileDropper, RFileInfo, RMessage } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst files = ref<File[]>([]);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"upload-stack\">\n          <r-message title=\"Upload policy\" color=\"help\">\n            Up to five files are accepted in this gallery sample.\n          </r-message>\n          <r-file-dropper v-model=\"files\" :config=\"{ maxCount: 5 }\" :file-info=\"false\" />\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"upload-stack\">\n          <r-file-dropper v-model=\"files\" :config=\"{ maxCount: 5 }\" />\n          <r-file-info v-model=\"files\" />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.upload-stack {\n  display: grid;\n  gap: 14px;\n}\n</style>\n",
  "/components/avatar": "<script setup lang=\"ts\">\nimport { RAvatar, RBadge } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"avatar-row\">\n          <r-avatar text=\"RF\" :size=\"32\" />\n          <r-avatar text=\"WS\" />\n          <r-avatar text=\"OP\" :size=\"56\" />\n          <r-badge value=\"3\" color=\"success\">\n            <r-avatar text=\"AD\" />\n          </r-badge>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"avatar-list\">\n          <div class=\"avatar-item\"><r-avatar text=\"RF\" /><span>Reta Future</span></div>\n          <div class=\"avatar-item\"><r-avatar text=\"EU\" /><span>Paper EU-1</span></div>\n          <div class=\"avatar-item\"><r-avatar text=\"DV\" /><span>Development</span></div>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.avatar-row,\n.avatar-list {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  align-items: center;\n}\n\n.avatar-list {\n  flex-direction: column;\n  align-items: stretch;\n}\n\n.avatar-item {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  color: var(--mcsl-text-color-regular);\n}\n</style>\n",
  "/components/tag": "<script setup lang=\"ts\">\nimport { RBadge, RButton, RTag } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"tag-row\">\n          <r-tag color=\"surface\">Surface</r-tag>\n          <r-tag color=\"primary\">Primary</r-tag>\n          <r-tag color=\"success\">Healthy</r-tag>\n          <r-tag color=\"warning\">Warning</r-tag>\n          <r-tag color=\"danger\">Danger</r-tag>\n          <r-tag color=\"help\">Help</r-tag>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"tag-row\">\n          <r-badge value=\"8\" color=\"danger\">\n            <r-button icon=\"fas fa-bell\">Notifications</r-button>\n          </r-badge>\n          <r-tag color=\"success\">Running</r-tag>\n          <r-tag color=\"primary\">Java 21</r-tag>\n          <r-tag color=\"help\">Paper</r-tag>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.tag-row {\n  display: flex;\n  gap: 10px;\n  flex-wrap: wrap;\n  align-items: center;\n}\n</style>\n",
  "/components/table": "<script setup lang=\"ts\">\nimport { RTable } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst columns = [\"Name\", \"Status\", \"Version\", \"Players\"];\nconst rows = [\n  [\"Paper EU-1\", \"Running\", \"1.21.1\", 12],\n  [\"Fabric Dev\", \"Stopped\", \"1.20.4\", 0],\n  [\"Velocity Edge\", \"Starting\", \"3.4.0\", 48],\n];\n\nconst denseRows = [\n  [\"CPU\", \"18%\", \"Normal\"],\n  [\"Memory\", \"4.1 GB\", \"Normal\"],\n  [\"Disk\", \"72%\", \"Warning\"],\n  [\"Network\", \"41 ms\", \"Normal\"],\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <r-table :columns=\"columns\" :rows=\"rows\" />\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"table-stack\">\n          <r-table :columns=\"columns\" :rows=\"rows\" />\n          <r-table :columns=\"['Metric', 'Value', 'State']\" :rows=\"denseRows\" />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.table-stack {\n  display: grid;\n  gap: 16px;\n}\n</style>\n",
  "/components/data-table": "<script setup lang=\"ts\">\nimport { RButton, RDataTable, RTag } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst selectedKeys = ref<string[]>([\"paper-eu\"]);\nconst sortBy = ref(\"players\");\nconst sortOrder = ref<\"asc\" | \"desc\" | null>(\"desc\");\n\nconst columns = [\n  { key: \"name\", title: \"Name\", sortable: true, width: \"minmax(180px, 1.2fr)\" },\n  { key: \"status\", title: \"Status\", sortable: true, width: \"120px\" },\n  { key: \"version\", title: \"Version\", width: \"120px\" },\n  { key: \"players\", title: \"Players\", sortable: true, align: \"right\" as const, width: \"110px\" },\n];\n\nconst rows = [\n  { id: \"paper-eu\", name: \"Paper EU-1\", status: \"Online\", version: \"1.21.5\", players: 12 },\n  { id: \"forge-us\", name: \"Forge US-2\", status: \"Installing\", version: \"1.20.1\", players: 0 },\n  { id: \"proxy-sg\", name: \"Velocity SG\", status: \"Online\", version: \"3.4.0\", players: 48 },\n  { id: \"fabric-cn\", name: \"Fabric CN-Dev\", status: \"Offline\", version: \"1.21.4\", players: 0 },\n];\n\nfunction statusColor(status: unknown) {\n  if (status === \"Online\") return \"success\";\n  if (status === \"Installing\") return \"warning\";\n  return \"surface\";\n}\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample title=\"Data Table\">\n        <r-data-table\n          v-model:selected-keys=\"selectedKeys\"\n          v-model:sort-by=\"sortBy\"\n          v-model:sort-order=\"sortOrder\"\n          :columns=\"columns\"\n          :rows=\"rows\"\n          selectable\n        >\n          <template #cell-status=\"{ value }\">\n            <r-tag :color=\"statusColor(value)\" size=\"small\">{{ value }}</r-tag>\n          </template>\n          <template #actions>\n            <r-button size=\"small\" type=\"text\">Open</r-button>\n          </template>\n        </r-data-table>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample title=\"States\">\n        <div class=\"datatable-stack\">\n          <r-data-table :columns=\"columns\" :rows=\"[]\" />\n          <r-data-table :columns=\"columns\" :rows=\"rows.slice(0, 2)\" loading />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.datatable-stack {\n  display: grid;\n  gap: 16px;\n}\n</style>\n",
  "/components/message": "<script setup lang=\"ts\">\nimport { RButton, RMessage } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"message-grid\">\n          <r-message title=\"Instance ready\" color=\"success\" closeable>\n            Paper EU-1 is online and accepting console commands.\n          </r-message>\n          <r-message title=\"Version drift\" color=\"warning\" closeable>\n            Three plugins were built against an older server API.\n          </r-message>\n          <r-message title=\"Daemon rejected request\" color=\"danger\" closeable>\n            The selected instance is locked by another operation.\n          </r-message>\n          <r-message title=\"Queue updated\" color=\"help\" closeable>\n            Backup jobs will run after the current upload finishes.\n          </r-message>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"message-grid\">\n          <r-message title=\"Borderless surface\" color=\"primary\">\n            Status messages use a quiet tinted background and keep the icon aligned to the text rhythm.\n          </r-message>\n          <r-message title=\"Outlined surface\" color=\"danger\" variant=\"outlined\">\n            Use the outlined variant when the message sits on a dense or similarly tinted surface.\n          </r-message>\n          <r-message color=\"surface\" icon=\"fas fa-terminal\" variant=\"soft\">\n            Console output paused while the daemon reconnects.\n            <template #buttons=\"{ close }\">\n              <r-button size=\"small\" type=\"text\" @click=\"close\">Dismiss</r-button>\n              <r-button size=\"small\" type=\"primary\" color=\"primary\">Reconnect</r-button>\n            </template>\n          </r-message>\n          <r-message color=\"help\" icon=\"fas fa-circle-info\" variant=\"text\">\n            Inline messages keep the same spacing model without drawing a container.\n          </r-message>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.message-grid {\n  display: grid;\n  gap: 12px;\n}\n</style>\n",
  "/components/kbd": "<script setup lang=\"ts\">\nimport { RKbd } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"kbd-row\">\n          <r-kbd size=\"small\">Esc</r-kbd>\n          <r-kbd>Ctrl</r-kbd>\n          <r-kbd>K</r-kbd>\n          <r-kbd>Enter</r-kbd>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"shortcut-list\">\n          <span><r-kbd>Ctrl</r-kbd><r-kbd>K</r-kbd></span>\n          <span>Command palette</span>\n          <span><r-kbd>Esc</r-kbd></span>\n          <span>Close overlay</span>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.kbd-row,\n.shortcut-list span:first-child,\n.shortcut-list span:nth-child(3) {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  align-items: center;\n}\n\n.shortcut-list {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr);\n  gap: 12px 16px;\n  align-items: center;\n  color: var(--mcsl-text-color-regular);\n}\n</style>\n",
  "/components/editor": "<script setup lang=\"ts\">\nimport { RCodeEditor, RCopyableText } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst value = ref(`{\n  \"name\": \"Future Paper EU-1\",\n  \"runtime\": \"java-21\",\n  \"core\": \"paper-1.21.1-43.jar\",\n  \"memory\": 4096\n}`);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"editor-meta\">\n          <r-copyable-text>daemon_instance.json</r-copyable-text>\n          <r-copyable-text>UTF-8</r-copyable-text>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"editor-wrap\">\n          <r-code-editor v-model=\"value\" default-lang=\"json\" />\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.editor-meta {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n.editor-wrap {\n  min-height: 360px;\n}\n</style>\n",
  "/components/accordion": "<script setup lang=\"ts\">\nimport { RAccordion, RAccordionPanel, RCollapsablePanel, RMessage } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst activeSingle = ref([\"runtime\"]);\nconst activeMultiple = ref([\"memory\", \"network\"]);\nconst collapsed = ref(false);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample title=\"Accordion\">\n        <r-accordion v-model=\"activeSingle\" class=\"accordion-surface\">\n          <r-accordion-panel name=\"runtime\" header=\"Runtime\">\n            Java path, launch arguments, and environment variables.\n          </r-accordion-panel>\n          <r-accordion-panel name=\"network\" header=\"Network\">\n            Ports, address binding, proxy, and query visibility.\n          </r-accordion-panel>\n          <r-accordion-panel name=\"danger\" header=\"Danger Zone\" disabled>\n            Disabled panels keep their context without accepting input.\n          </r-accordion-panel>\n        </r-accordion>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.multiplePanels')\">\n        <div class=\"accordion-stack\">\n          <r-accordion v-model=\"activeMultiple\" multiple class=\"accordion-surface\">\n            <r-accordion-panel name=\"memory\" header=\"Memory\">\n              Allocate a predictable heap range for the selected server profile.\n            </r-accordion-panel>\n            <r-accordion-panel name=\"network\" header=\"Network\">\n              Keep public and daemon-only ports visually separated.\n            </r-accordion-panel>\n            <r-accordion-panel name=\"backup\" header=\"Backup\">\n              Scheduled snapshots can be opened together with runtime settings.\n            </r-accordion-panel>\n          </r-accordion>\n\n          <r-collapsable-panel v-model:collapsed=\"collapsed\" header=\"Standalone Collapsible\" shadow=\"never\">\n            <r-message color=\"help\" title=\"Composable primitive\">\n              Use CollapsablePanel when a single area needs disclosure without group state.\n            </r-message>\n          </r-collapsable-panel>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.accordion-stack {\n  display: grid;\n  gap: 14px;\n}\n\n.accordion-surface {\n  min-width: 0;\n}\n</style>\n",
  "/components/tree": "<script setup lang=\"ts\">\nimport { RMessage, RTree, RTreeSelect } from \"reta-ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst expandedKeys = ref([\"instances\", \"configs\"]);\nconst selectedKeys = ref([\"paper-eu\"]);\nconst selectedFile = ref(\"server-properties\");\n\nconst treeItems = [\n  {\n    key: \"instances\",\n    label: \"Instances\",\n    icon: \"fas fa-server\",\n    children: [\n      { key: \"paper-eu\", label: \"Paper EU-1\", icon: \"fas fa-cube\" },\n      { key: \"forge-us\", label: \"Forge US-2\", icon: \"fas fa-cube\" },\n    ],\n  },\n  {\n    key: \"configs\",\n    label: \"Configs\",\n    icon: \"fas fa-folder\",\n    children: [\n      { key: \"server-properties\", label: \"server.properties\", icon: \"fas fa-file-lines\" },\n      { key: \"permissions\", label: \"permissions.yml\", icon: \"fas fa-file-code\" },\n      { key: \"locked\", label: \"locked.yml\", icon: \"fas fa-lock\", disabled: true },\n    ],\n  },\n  {\n    key: \"backups\",\n    label: \"Backups\",\n    icon: \"fas fa-box-archive\",\n    children: [\n      { key: \"daily\", label: \"Daily snapshots\", icon: \"fas fa-clock\" },\n      { key: \"manual\", label: \"Manual exports\", icon: \"fas fa-download\" },\n    ],\n  },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample title=\"Tree\">\n        <r-tree\n          v-model:expanded-keys=\"expandedKeys\"\n          v-model:selected-keys=\"selectedKeys\"\n          :items=\"treeItems\"\n        />\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.treeSelect')\">\n        <div class=\"tree-stack\">\n          <r-tree-select v-model=\"selectedFile\" :items=\"treeItems\" placeholder=\"Choose file\" />\n          <r-message color=\"help\" title=\"Selected key\">{{ selectedFile }}</r-message>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.tree-stack {\n  display: grid;\n  gap: 14px;\n}\n</style>\n",
  "/components/compositions": "<script setup lang=\"ts\">\nimport { RButton, RCard, RMessage, RMeterGroup, RNavTabs, RTag } from \"reta-ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport GalleryExample from \"../components/GalleryExample.vue\";\n\nconst qualities = [\n  \"Calmer surfaces\",\n  \"Smaller radii\",\n  \"Softer shadows\",\n  \"Clear hierarchy\",\n];\n\nconst tabs = [\n  { label: \"Overview\", icon: \"fas fa-gauge\" },\n  { label: \"Console\", icon: \"fas fa-terminal\" },\n  { label: \"Backups\", icon: \"fas fa-clock-rotate-left\" },\n];\n\nconst meter = {\n  length: 100,\n  values: [\n    { label: \"CPU\", length: 18, type: \"success\" },\n    { label: \"RAM\", length: 42, type: \"primary\" },\n    { label: \"Disk\", length: 64, type: \"warning\" },\n  ],\n};\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <GalleryExample :title=\"$t('gallery.sections.basic')\">\n        <div class=\"composition\">\n          <div class=\"composition-main\">\n            <h3>Server Overview</h3>\n            <p>\n              Brand color guides orientation while spacing, typography, and surface hierarchy do most of the work.\n            </p>\n          </div>\n          <div class=\"composition-rail\">\n            <r-tag v-for=\"quality in qualities\" :key=\"quality\">{{ quality }}</r-tag>\n          </div>\n        </div>\n      </GalleryExample>\n    </template>\n\n    <template #demo>\n      <GalleryExample :title=\"$t('gallery.sections.example')\">\n        <div class=\"instance-shell\">\n          <div class=\"instance-header\">\n            <div>\n              <h3>Paper EU-1</h3>\n              <div class=\"tag-row\">\n                <r-tag color=\"success\">Online</r-tag>\n                <r-tag color=\"primary\">Java 21</r-tag>\n                <r-tag color=\"help\">Paper</r-tag>\n              </div>\n            </div>\n            <r-button type=\"primary\" color=\"primary\" icon=\"fas fa-terminal\">Console</r-button>\n          </div>\n          <r-nav-tabs :tabs=\"tabs\" />\n          <r-card title=\"Runtime\" description=\"Current resource allocation and process health.\">\n            <div class=\"card-stack\">\n              <r-meter-group :meter=\"meter\" />\n              <r-message title=\"Stable\" color=\"success\">\n                CPU, memory, and disk usage are inside the expected range.\n              </r-message>\n            </div>\n          </r-card>\n        </div>\n      </GalleryExample>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.composition {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 220px;\n  gap: 20px;\n}\n\n.composition-main h3,\n.instance-header h3 {\n  margin: 0;\n  font-weight: 600;\n}\n\n.composition-main p {\n  color: var(--mcsl-text-color-regular);\n  line-height: 1.7;\n}\n\n.composition-rail,\n.tag-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n  align-content: start;\n}\n\n.instance-shell,\n.card-stack {\n  display: grid;\n  gap: 16px;\n}\n\n.instance-header {\n  display: flex;\n  justify-content: space-between;\n  gap: 16px;\n  align-items: start;\n}\n\n@media (max-width: 980px) {\n  .composition,\n  .instance-header {\n    grid-template-columns: 1fr;\n  }\n\n  .instance-header {\n    flex-direction: column;\n  }\n}\n</style>\n",
};
